public E remove(int i) {
		int n = elements.size();

		if(i < 0 || i >= n)
			throw new ArrayIndexOutOfBoundsException("index "+i+" does not exist");

		if(n > 0) {
			if( elements.get( i ) == null )
				throw new NullPointerException("no element stored at index " + i);

			if(i == (n - 1)) {
				return elements.remove( i );
			} else {
				E e = elements.get(i);
				elements.set(i, null);
				freeIndices.add(i);
				return e;
			}
		}

		throw new ArrayIndexOutOfBoundsException("index "+i+" does not exist");






	}
